using namespace std;

int secondLargest(int arr[], int n) {
    if (n == 0 || n == 1)
        return -1;
    
    // Partition the array into two parts: elements smaller than pivot and elements greater than pivot
    int i = partition(arr, 0, n-1);
    
    // If the index of the pivot is equal to n-2, then the second largest number is at the rightmost position
    if (i + 1 == n - 1)
        return arr[n-1];
    
    // Recursively call the function on the left half of the array
    else if (i + 1 < n - 1)
        return secondLargest(arr, i+1);
    
    // Recursively call the function on the right half of the array
    else 
        return secondLargest(arr, i+1);
}

// Function to perform partitioning
int partition(int arr[], int low, int high) {
    int pivot = arr[high];   // Choose the last element as the pivot
    
    int i = (low - 1);  // Index of smaller element
        
    for (int j = low; j <= high - 1; j++) {
        // If current element is smaller than or equal to pivot
        if (arr[j] <= pivot) {
            i++;     // Increment index of smaller element
            swap(arr[i], arr[j]);
        }
    }
    
    swap(arr[i + 1], arr[high]);
    return (i + 1);
}

